INSERT INTO public.sop_templates VALUES ('8de6fd04-c6d7-5fe9-84b8-7dade523311b', '4ab122a8-78f1-5a68-8277-7f7199255208', 'Aetna PT via Claritev — NC', '12a8634c-aa9b-577b-a0d5-3ab5599c162a', 'NC', 'Physical Therapy', '75013edb-7dd1-5747-ae0e-c1aa6e0d6e1c', '[{"title": "Verify CAQH Profile", "dayOffset": 0, "description": "Confirm CAQH is attested within 120 days and all required documents are uploaded.", "sopStepTemplates": [{"step": "Log into CAQH ProView with {{provider.caqhId}}", "dataFieldTokens": ["provider.caqhId"]}, {"step": "Verify attestation date is within last 120 days", "dataFieldTokens": ["provider.caqhLastAttestedDate"]}, {"step": "Confirm taxonomy code {{provider.taxonomyCode}} is listed", "dataFieldTokens": ["provider.taxonomyCode"]}, {"step": "Re-attest if needed and notify provider via email", "dataFieldTokens": []}]}, {"title": "Submit via Claritev Portal", "dayOffset": 2, "description": "File the credentialing application through Claritev (do NOT submit directly to Aetna).", "sopStepTemplates": [{"step": "Log into provider.claritev.com", "dataFieldTokens": []}, {"step": "Start new application — NPI {{provider.npi}}, Group TIN {{group.tin}}", "dataFieldTokens": ["provider.npi", "group.tin"]}, {"step": "Attach group NPI Type-2 {{group.npiType2}}", "dataFieldTokens": ["group.npiType2"]}, {"step": "Upload state license, malpractice COI, and W-9", "dataFieldTokens": []}, {"step": "Submit and screenshot the confirmation page", "dataFieldTokens": []}]}, {"title": "Confirm Submission Receipt", "dayOffset": 7, "description": "Confirm Claritev acknowledged the application.", "sopStepTemplates": [{"step": "Check Claritev portal for receipt confirmation", "dataFieldTokens": []}, {"step": "If no confirmation, call Claritev support", "dataFieldTokens": []}, {"step": "Log touch with outcome", "dataFieldTokens": []}]}, {"title": "14-Day Follow-Up", "dayOffset": 21, "description": "Check status with Claritev.", "sopStepTemplates": [{"step": "Pull status from Claritev portal for NPI {{provider.npi}}", "dataFieldTokens": ["provider.npi"]}, {"step": "If pending more than 14 days, escalate to Claritev rep", "dataFieldTokens": []}, {"step": "Log next follow-up date", "dataFieldTokens": []}]}, {"title": "Confirm Effective Date", "dayOffset": 90, "description": "Get the panel effective date in writing from Aetna.", "sopStepTemplates": [{"step": "Request effective date letter from Aetna provider relations", "dataFieldTokens": []}, {"step": "Update case with confirmedEffectiveDate", "dataFieldTokens": []}, {"step": "Move case status to Active", "dataFieldTokens": []}]}]', '2026-06-10 04:50:27.297544+00', '2026-06-10 04:50:27.297544+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.sop_templates VALUES ('e573bb2e-dcdd-59c3-ac53-49331290b66e', '4ab122a8-78f1-5a68-8277-7f7199255208', 'UHC PT via Optum — TX', '12a8634c-aa9b-577b-a0d5-3ab5599c162a', 'TX', 'Physical Therapy', 'f0f3fa7c-49be-583b-a65e-e27ac2373a58', '[{"title": "Verify CAQH Profile", "dayOffset": 0, "description": "Confirm CAQH attestation and taxonomy {{provider.taxonomyCode}}.", "sopStepTemplates": [{"step": "Open CAQH ProView with {{provider.caqhId}}", "dataFieldTokens": ["provider.caqhId"]}, {"step": "Confirm taxonomy {{provider.taxonomyCode}}", "dataFieldTokens": ["provider.taxonomyCode"]}, {"step": "Re-attest if outside 120 days", "dataFieldTokens": []}]}, {"title": "Submit via Optum Physical Health Portal", "dayOffset": 2, "description": "Never contact UHC directly — submit only via Optum.", "sopStepTemplates": [{"step": "Log into provider.optumphysicalhealth.com", "dataFieldTokens": []}, {"step": "Start application with NPI {{provider.npi}}, Group TIN {{group.tin}}", "dataFieldTokens": ["provider.npi", "group.tin"]}, {"step": "Attach Type-2 NPI {{group.npiType2}}", "dataFieldTokens": ["group.npiType2"]}, {"step": "Submit and save confirmation", "dataFieldTokens": []}]}, {"title": "Confirm Submission Receipt", "dayOffset": 7, "description": "Confirm Optum acknowledged the application.", "sopStepTemplates": [{"step": "Check Optum portal", "dataFieldTokens": []}, {"step": "Call Optum if no acknowledgement", "dataFieldTokens": []}, {"step": "Log touch", "dataFieldTokens": []}]}, {"title": "14-Day Follow-Up", "dayOffset": 21, "description": "Pull current status from Optum.", "sopStepTemplates": [{"step": "Pull status for NPI {{provider.npi}}", "dataFieldTokens": ["provider.npi"]}, {"step": "Escalate to Optum rep if stuck", "dataFieldTokens": []}, {"step": "Set next follow-up", "dataFieldTokens": []}]}, {"title": "Confirm Effective Date", "dayOffset": 90, "description": "Document panel effective date.", "sopStepTemplates": [{"step": "Request effective date confirmation from Optum", "dataFieldTokens": []}, {"step": "Update case", "dataFieldTokens": []}, {"step": "Notify billing team", "dataFieldTokens": []}]}]', '2026-06-10 04:50:27.297544+00', '2026-06-10 04:50:27.297544+00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.sop_templates VALUES ('e53f8a51-f874-5be3-93a7-a130f588ae2a', '13fddb31-a2ac-5be4-aae9-01eed273b918', 'BCBS KS — Direct via Availity', '074e0781-c267-5f42-b2a6-5b9bb8bdcdb3', 'KS', 'Physical Therapy', '9d51dbb8-d636-5d9f-b021-1a8ab1070f8c', '[{"title": "Complete Availity Application", "dayOffset": 0, "description": "Begin BCBS KS application directly via Availity.", "sopStepTemplates": [{"step": "Log into availity.com", "dataFieldTokens": []}, {"step": "Start BCBS KS application — NPI {{provider.npi}}, Group TIN {{group.tin}}", "dataFieldTokens": ["provider.npi", "group.tin"]}, {"step": "Attach Type-2 NPI {{group.npiType2}} and taxonomy {{provider.taxonomyCode}}", "dataFieldTokens": ["group.npiType2", "provider.taxonomyCode"]}, {"step": "Save draft", "dataFieldTokens": []}]}, {"title": "Authorize CAQH Pull", "dayOffset": 2, "description": "Grant BCBS access to CAQH within 45 days of submission.", "sopStepTemplates": [{"step": "Log into CAQH with {{provider.caqhId}}", "dataFieldTokens": ["provider.caqhId"]}, {"step": "Add Blue Cross Blue Shield of Kansas as authorized payer", "dataFieldTokens": []}, {"step": "Re-attest", "dataFieldTokens": []}]}, {"title": "Follow-Up", "dayOffset": 14, "description": "Check progress with Availity / BCBS.", "sopStepTemplates": [{"step": "Pull status from Availity for NPI {{provider.npi}}", "dataFieldTokens": ["provider.npi"]}, {"step": "Call BCBS KS provider services if stuck", "dataFieldTokens": []}, {"step": "Log touch and next follow-up", "dataFieldTokens": []}]}, {"title": "Confirm Approval", "dayOffset": 60, "description": "Capture approval letter and effective date.", "sopStepTemplates": [{"step": "Download approval letter from Availity", "dataFieldTokens": []}, {"step": "Update case with effective date", "dataFieldTokens": []}, {"step": "Move case to Active", "dataFieldTokens": []}]}]', '2026-06-10 04:50:27.297544+00', '2026-06-10 04:50:27.297544+00') ON CONFLICT (id) DO NOTHING;
